const selected = $("GET SELECTED TOPIC1").first().json;
const material = $input.first().json;

if (!material || !material.id || String(material.userId) !== String(selected.userId)) {
  return [
    {
      json: {
        success: false,
        chatId: selected.chatId,
        errorMessage: "Sorry. Material not found."
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      materialId: material.id,
      userId: selected.userId,
      chatId: selected.chatId,
      title: material.title,
      url: material.url,
      content: material.content,
      summary: material.summary,
      keyPoints: material.keyPoints,
      mainConcepts: material.mainConcepts,
      difficulty: material.difficulty
    }
  }
];

const parts = $json.callbackData.split("|");

return [
  {
    json: {
      ...$json,
      sessionId: parts[1],
      questionId: parts[2],
      selectedAnswer: parts[3]
    }
  }
];

const answer = $('Parse Answer Callback').first().json;
const session = $input.first().json;

if (!session || !session.sessionId || String(session.userId) !== String(answer.userId)) {
  return [
    {
      json: {
        success: false,
        chatId: answer.chatId,
        errorMessage: "I could not find this quiz session. Please start again with /quiz."
      }
    }
  ];
}

if (session.status === "processing") {
  return [
    {
      json: {
        success: false,
        chatId: answer.chatId,
        errorMessage: "Please wait, I’m still checking your previous answer."
      }
    }
  ];
}

if (session.status === "completed") {
  return [
    {
      json: {
        success: false,
        chatId: answer.chatId,
        errorMessage: "This quiz is already completed. Send /quiz to start another one."
      }
    }
  ];
}

const currentQuestionIndex = Number(session.currentQuestionIndex || 0);
const clickedQuestionMatch = String(answer.questionId || "").match(/^Q(\d+)$/i);

if (clickedQuestionMatch) {
  const clickedQuestionIndex = Number(clickedQuestionMatch[1]) - 1;

  if (clickedQuestionIndex !== currentQuestionIndex) {
    return [
      {
        json: {
          success: false,
          chatId: answer.chatId,
          errorMessage: "This answer button is no longer active. Please answer the latest question."
        }
      }
    ];
  }
}

return [
  {
    json: {
      ...session,
      success: true,
      chatId: answer.chatId,
      userId: answer.userId,
      selectedAnswer: answer.selectedAnswer,
      selectedQuestionId: answer.questionId
    }
  }
];

const session = $('Find Active Session').first().json;
const quiz = $input.first().json;

if (!quiz || !quiz.questions) {
  return [
    {
      json: {
        success: false,
        chatId: session.chatId,
        errorMessage: "I could not find the quiz questions. Send /quiz to start again."
      }
    }
  ];
}

const questions = JSON.parse(quiz.questions);
const question = questions.find(q => q.id === session.selectedQuestionId);

if (!question) {
  return [
    {
      json: {
        success: false,
        chatId: session.chatId,
        errorMessage: "I could not find this question. Send /quiz to start again."
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      chatId: session.chatId,
      userId: session.userId,
      sessionId: session.sessionId,
      quizId: session.quizId,
      materialId: session.materialId,
      currentQuestionIndex: Number(session.currentQuestionIndex),
      previousAnswers: session.answers || "[]",
      questions,
      question,
      selectedAnswer: session.selectedAnswer
    }
  }
];

const context = $('Find Quiz Question').first().json;

const aiText =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  JSON.stringify($json);

let validation;
try {
  validation = JSON.parse(
    String(aiText)
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim()
  );
} catch (error) {
  validation = {
    isCorrect: String(context.selectedAnswer).trim().toUpperCase() === String(context.question.correctAnswer).trim().toUpperCase(),
    correctAnswer: context.question.correctAnswer,
    feedback: context.question.explanation
  };
}

const selected = String(context.selectedAnswer).trim().toUpperCase();
const correct = String(validation.correctAnswer || context.question.correctAnswer).trim().toUpperCase();
const isCorrect = typeof validation.isCorrect === 'boolean'
  ? validation.isCorrect
  : String(validation.isCorrect).toLowerCase() === 'true';

const answers = JSON.parse(context.previousAnswers || '[]');

answers.push({
  questionId: context.question.id,
  question: context.question.question,
  selectedAnswer: selected,
  correctAnswer: correct,
  isCorrect,
  feedback: validation.feedback || context.question.explanation
});

const nextIndex = context.currentQuestionIndex + 1;
const total = context.questions.length;

function label(key, value) {
  const text = `${key}) ${value || ''}`;
  return text.length > 60 ? text.slice(0, 57) + '...' : text;
}

if (nextIndex < total) {
  const nextQuestion = context.questions[nextIndex];

  return [
    {
      json: {
        mode: 'next_question',
        chatId: context.chatId,
        sessionId: context.sessionId,
        quizId: context.quizId,
        materialId: context.materialId,
        userId: context.userId,
        currentQuestionIndex: nextIndex,
        answers: JSON.stringify(answers),
        status: 'in_progress',
        score: 0,
        updatedDate: new Date().toISOString(),
        questionNumber: nextIndex + 1,
        totalQuestions: total,
        questionId: nextQuestion.id,
        question: nextQuestion.question,
        options: nextQuestion.options,
        replyMarkup: {
          inline_keyboard: [
            [{ text: label('A', nextQuestion.options.A), callback_data: `answer|${context.sessionId}|${nextQuestion.id}|A` }],
            [{ text: label('B', nextQuestion.options.B), callback_data: `answer|${context.sessionId}|${nextQuestion.id}|B` }],
            [{ text: label('C', nextQuestion.options.C), callback_data: `answer|${context.sessionId}|${nextQuestion.id}|C` }],
            [{ text: label('D', nextQuestion.options.D), callback_data: `answer|${context.sessionId}|${nextQuestion.id}|D` }]
          ]
        }
      }
    }
  ];
}

const correctCount = answers.filter(a => a.isCorrect).length;
const score = Math.round((correctCount / total) * 100);

const feedbackText = answers.map((a, index) => {
  const icon = a.isCorrect ? '✅' : '❌';
  if (a.isCorrect) return `Q${index + 1}: ${icon} Correct

`;
  return `Q${index + 1}: ${icon} Incorrect
Your answer: ${a.selectedAnswer}
Correct answer: ${a.correctAnswer}
Explanation: ${a.feedback}

`;
}).join('');

return [
  {
    json: {
      mode: 'complete',
      chatId: context.chatId,
      sessionId: context.sessionId,
      quizId: context.quizId,
      materialId: context.materialId,
      userId: context.userId,
      currentQuestionIndex: total,
      answers: JSON.stringify(answers),
      status: 'completed',
      score,
      updatedDate: new Date().toISOString(),
      finalText: `🎉 Quiz complete!

Score: ${score}%

${feedbackText}

You can start another quiz with: /quiz
or learn new material with: /learn https://example.com/article`
    }
  }
];

