const text = $input.first().json.text || "";
const parts = text.trim().split(/\s+/);
const url = parts[1];

if (!url || !/^https?:\/\//i.test(url)) {
  return [{
    json: {
      valid: false,
      errorMessage: "Please send a valid URL, for example: /learn https://example.com/article"
    }
  }];
}

return [{
  json: {
    valid: true,
    url,
    userId: String($input.first().json.userId),
    chatId: String($input.first().json.chatId),
    addedDate: new Date().toISOString()
  }
}];

const previous = $('CHECK VALID URL1').first().json;
const response = $json;

const html = response.body || response.data || response;

if (!html || typeof html !== "string") {
  return [
    {
      json: {
        ...previous,
        success: false,
        errorMessage: "I could not fetch readable content from this URL. Please try another URL."
      }
    }
  ];
}

const titleMatch = html.match(/<title[^>]*>(.*?)<\/title>/i);
const rawTitle = titleMatch ? titleMatch[1] : "Untitled material";

const title = rawTitle
  .replace(/&amp;/g, "&")
  .replace(/&nbsp;/g, " ")
  .replace(/\s+/g, " ")
  .trim();

let content = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
  .replace(/<header[\s\S]*?<\/header>/gi, " ")
  .replace(/<footer[\s\S]*?<\/footer>/gi, " ")
  .replace(/<nav[\s\S]*?<\/nav>/gi, " ")
  .replace(/<aside[\s\S]*?<\/aside>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&lt;/g, "<")
  .replace(/&gt;/g, ">")
  .replace(/&quot;/g, "\"")
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, " ")
  .trim();

if (content.length < 500) {
  return [
    {
      json: {
        ...previous,
        success: false,
        errorMessage: "I found the page, but could not extract enough readable article text. Try a different URL."
      }
    }
  ];
}

return [
  {
    json: {
      ...previous,
      success: true,
      title,
      content: content.slice(0, 15000),
      addedDate: new Date().toISOString()
    }
  }
];

const original = $('Clean HTML Content1').first().json;

const aiText =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  JSON.stringify($json);

let cleaned = String(aiText)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [
    {
      json: {
        ...original,
        success: false,
        errorMessage: "The Teacher AI returned invalid JSON. Please try again."
      }
    }
  ];
}

const materialId = `LM-${Date.now()}`;

return [
  {
    json: {
      id: materialId,
      userId: original.userId,
      chatId: original.chatId,
      url: original.url,
      title: parsed.title || original.title,
      content: original.content,
      summary: parsed.summary,
      keyPoints: JSON.stringify(parsed.keyPoints || []),
      mainConcepts: JSON.stringify(parsed.mainConcepts || []),
      difficulty: parsed.difficulty || "intermediate",
      addedDate: original.addedDate,
      success: true
    }
  }
];

