const trigger = $("Normalize Telegram Input1").first().json;
const userId = trigger.userId;
const chatId = trigger.chatId;

const rows = $input.all().map(item => item.json);

const userMaterials = rows.filter(row =>
  String(row.userId) === String(userId)
);

if (userMaterials.length === 0) {
  return [
    {
      json: {
        chatId,
        text: "You do not have any saved materials yet.\n\nSend: /learn https://example.com/article to add a new article",
        replyMarkup: null
      }
    }
  ];
}

const buttons = userMaterials.slice(0, 10).map(material => {
  const title = material.title || "Untitled material";

  return [
    {
      text: title.slice(0, 45),
      callback_data: `topic|${material.id}`
    }
  ];
});

return [
  {
    json: {
      chatId,
      text: "Choose a saved topic for your quiz:",
      replyMarkup: {
        inline_keyboard: buttons
      }
    }
  }
];

const update = $json;

let type = "";
let text = "";
let callbackData = "";
let callbackQueryId = "";
let chatId = "";
let userId = "";
let messageId = "";

if (update.message) {
  type = "message";
  text = update.message.text || "";
  chatId = String(update.message.chat.id);
  userId = String(update.message.from.id);
  messageId = String(update.message.message_id || "");
}

if (update.callback_query) {
  type = "callback";
  callbackData = update.callback_query.data || "";
  callbackQueryId = update.callback_query.id;
  chatId = String(update.callback_query.message.chat.id);
  userId = String(update.callback_query.from.id);
  messageId = String(update.callback_query.message.message_id || "");
}

let command = "unknown";
let url = "";

if (type === "message") {
  const trimmed = text.trim();

  if (trimmed === "/start") {
    command = "start";
  } else if (trimmed.startsWith("/learn")) {
    command = "learn";
    const parts = trimmed.split(/\s+/);
    url = parts[1] || "";
  } else if (trimmed === "/quiz") {
    command = "quiz";
  }
}

if (type === "callback") {
  const parts = callbackData.split("|");

  if (parts[0] === "start_quiz") {
    command = "start_quiz";
  } else if (parts[0] === "topic") {
    command = "topic_selected";
  } else if (parts[0] === "answer") {
    command = "answer";
  }
}

return [
  {
    json: {
      type,
      command,
      text,
      url,
      callbackData,
      callbackQueryId,
      chatId,
      userId,
      messageId,
      receivedAt: new Date().toISOString()
    }
  }
];

const material = $('Prepare Selected Material').first().json;

const aiText =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  JSON.stringify($json);

const cleaned = String(aiText)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [
    {
      json: {
        success: false,
        chatId: material.chatId,
        errorMessage: "The Examiner AI returned invalid quiz JSON. Please try again."
      }
    }
  ];
}

if (!parsed.questions || parsed.questions.length !== 5) {
  return [
    {
      json: {
        success: false,
        chatId: material.chatId,
        errorMessage: "The quiz was not generated correctly. Please try again."
      }
    }
  ];
}

const quizId = `QUIZ-${Date.now()}`;
const sessionId = `SESSION-${Date.now()}`;

return [
  {
    json: {
      success: true,
      quizId,
      sessionId,
      materialId: material.materialId,
      userId: material.userId,
      chatId: material.chatId,
      questions: JSON.stringify(parsed.questions),
      currentQuestionIndex: 0,
      answers: JSON.stringify([]),
      status: "in_progress",
      score: 0,
      createdDate: new Date().toISOString(),
      updatedDate: new Date().toISOString()
    }
  }
];

const session = $('Parse Quiz Output1').first().json;
const questions = JSON.parse(session.questions);
const q = questions[0];

function label(key, value) {
  const text = `${key}) ${value || ''}`;
  return text.length > 60 ? text.slice(0, 57) + '...' : text;
}

return [
  {
    json: {
      chatId: session.chatId,
      sessionId: session.sessionId,
      questionId: q.id,
      questionNumber: 1,
      totalQuestions: questions.length,
      question: q.question,
      options: q.options,
      replyMarkup: {
        inline_keyboard: [
          [{ text: label('A', q.options.A), callback_data: `answer|${session.sessionId}|${q.id}|A` }],
          [{ text: label('B', q.options.B), callback_data: `answer|${session.sessionId}|${q.id}|B` }],
          [{ text: label('C', q.options.C), callback_data: `answer|${session.sessionId}|${q.id}|C` }],
          [{ text: label('D', q.options.D), callback_data: `answer|${session.sessionId}|${q.id}|D` }]
        ]
      }
    }
  }
];

const data = $('Normalize Telegram Input1').first().json.callbackData || "";

if (!data.startsWith("start_quiz|") && !data.startsWith("topic|")) {
  return [];
}

const materialId = data.split("|")[1];

return [
  {
    json: {
      ...$json,
      materialId
    }
  }
];

