const answer = $json;
const data = $getWorkflowStaticData('global');
const now = Date.now();
const ttlMs = 2 * 60 * 1000;
const sessionId = answer.sessionId;
const key = `quizAnswerLock:${answer.userId}:${sessionId}`;
const existing = data[key];

if (existing && Number(existing.expiresAt || 0) > now) {
  return [
    {
      json: {
        ...answer,
        success: false,
        lockAcquired: false,
        errorMessage: "Please wait, I’m still checking your previous answer."
      }
    }
  ];
}

data[key] = {
  userId: answer.userId,
  chatId: answer.chatId,
  sessionId,
  questionId: answer.questionId,
  createdAt: now,
  expiresAt: now + ttlMs
};

return [
  {
    json: {
      ...answer,
      success: true,
      lockAcquired: true,
      lockKey: key,
      lockExpiresAt: new Date(now + ttlMs).toISOString()
    }
  }
];

