const answer = $('Acquire Answer Lock').first().json;
const data = $getWorkflowStaticData('global');
const key = answer.lockKey || `quizAnswerLock:${answer.userId}:${answer.sessionId}`;

delete data[key];

return [
  {
    json: {
      released: true,
      lockKey: key,
      chatId: answer.chatId,
      sessionId: answer.sessionId,
      releasedAt: new Date().toISOString()
    }
  }
];
